#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_FULL_FEMENU_ENTRY

class BoxText;
class GraphicalMenuSystem;

class MainFrontEnd {
public:
    void ResizeCareerBox(int height);
};

class CareerMenu : public FEMenu {
public:
    enum {
        ContinueEntry,
        NewEntry,
        LoadEntry,
        SaveEntry,
        OKEntry,
        CancelEntry,
        NumEntries
    };

    FEMenuEntry *entry[NumEntries];
    BoxText *warning;
    bool warning_up;
    GraphicalMenuSystem *system;
    int warning_bottom;
    int regular_bottom;

    virtual void Draw();
    void StartWarning();
};

__asm__(".equ ResizeCareerBox__12MainFrontEndi, 0x0017F550");

void CareerMenu::StartWarning()
{
	warning_up = true;
	setHigh(entry[SaveEntry]);
	entry[ContinueEntry]->Disable(true);
	entry[LoadEntry]->Disable(true);
	entry[NewEntry]->Disable(true);
	entry[SaveEntry]->Disable(false);
	entry[OKEntry]->Disable(false);
	entry[CancelEntry]->Disable(false);
	((MainFrontEnd*) parent)->ResizeCareerBox(warning_bottom);
}
